// ================== CONFIGURE AQUI ==================
const CONFIG = {
  TOKEN: 'TROQUE-POR-UMA-CHAVE-SECRETA',   // a mesma chave das Configurações do copiloto
  SUBDOMINIO: 'SEU-SUBDOMINIO',            // ex.: odontoweiss  (de odontoweiss.kommo.com)
  PIPELINE_ID: null,                       // ID do funil (número) ou null para o funil padrão
  STATUS: {                                // IDs das etapas do funil (null = não altera a etapa)
    negociacao: null,                      // ex.: etapa "Orçamento apresentado"
    fechado: 142,                          // 142 = Venda ganha (padrão do Kommo)
    perdido: 143                           // 143 = Venda perdida (padrão do Kommo)
  },
  RESPONSAVEL_ID: null                     // ID do usuário responsável (opcional)
};
// ====================================================

const body = $input.first().json.body || {};
if (body.token !== CONFIG.TOKEN) throw new Error('Chave do copiloto inválida');
if (body.evento === 'teste') return [{ json: { teste: true } }];

const p = body.paciente || {};
const tel = String(p.telefone || '').replace(/\D/g, '');
if (!tel) throw new Error('Telefone do paciente ausente');
const telNacional = tel.startsWith('55') && tel.length > 11 ? tel.slice(2) : tel;

const c = body.consulta || {};
const o = body.orcamento || {};
const resultado = body.resultado || 'negociacao';
const statusId = CONFIG.STATUS[resultado] || null;
const canal = c.canal === 'presencial' ? 'Presencial' : 'WhatsApp';

const tags = ['Copiloto', canal, c.unidade, o.tratamento].filter(Boolean).map(name => ({ name }));
if ((body.temperatura || 0) >= 70) tags.push({ name: 'Lead quente' });

// Nota: resumo + transcrição (limitada para não estourar o tamanho da nota)
let transcricao = (body.transcricao || [])
  .map(m => `${m.quem === 'cliente' ? 'Paciente' : 'Clínica'}: ${m.texto}`).join('\n');
if (transcricao.length > 12000) transcricao = '…\n' + transcricao.slice(-12000);
const nota = (body.resumo || 'Consulta registrada pelo copiloto') + (transcricao ? '\n\n— TRANSCRIÇÃO —\n' + transcricao : '');

const lead = { price: Math.round(o.valor || 0) };
if (statusId) lead.status_id = statusId;
if (CONFIG.PIPELINE_ID) lead.pipeline_id = CONFIG.PIPELINE_ID;
if (CONFIG.RESPONSAVEL_ID) lead.responsible_user_id = CONFIG.RESPONSAVEL_ID;

return [{ json: {
  teste: false,
  base: `https://${CONFIG.SUBDOMINIO}.kommo.com`,
  telefone: tel, telefone_busca: telNacional,
  nome: p.nome || 'Paciente', origem: p.origem || '',
  lead_id_informado: p.lead_id ? Number(p.lead_id) : null,
  lead_base: lead, tags, nota,
  proximo_contato: body.proximo_contato || null,
  motivo_perda: body.motivo_perda || '',
  resultado
}}];

const prep = $('Validar e preparar').first().json;
let d = {};
try { const raw = $input.first().json.data; d = raw ? (typeof raw === 'string' ? JSON.parse(raw) : raw) : {}; } catch (e) { d = {}; }

const contato = (d._embedded && d._embedded.contacts || [])[0] || null;
let leadId = prep.lead_id_informado;
if (!leadId && contato) {
  const leads = (contato._embedded && contato._embedded.leads) || [];
  if (leads.length) leadId = Math.max(...leads.map(l => l.id)); // lead mais recente do contato
}

// corpo para ATUALIZAR um lead existente
const patch = { ...prep.lead_base, tags_to_add: prep.tags };

// corpo para CRIAR lead (+ contato, se ainda não existir)
const novo = {
  name: `${prep.nome} — Copiloto`,
  ...prep.lead_base,
  _embedded: {
    tags: prep.tags,
    contacts: [contato ? { id: contato.id } : {
      first_name: prep.nome,
      custom_fields_values: [{ field_code: 'PHONE', values: [{ value: '+' + prep.telefone, enum_code: 'MOB' }] }]
    }]
  }
};

return [{ json: { ...prep, contato_id: contato ? contato.id : null, lead_id: leadId || null, patch, novo: [novo] } }];

const prep = $('Decidir lead').first().json;
const r = $input.first().json;
const leadId = r.id || (Array.isArray(r) && r[0] && r[0].id) || prep.lead_id;
let tarefa = null;
if (prep.proximo_contato) {
  tarefa = [{
    text: `Retornar contato com ${prep.nome} (combinado na consulta — copiloto)`,
    complete_till: Math.floor(new Date(prep.proximo_contato).getTime() / 1000),
    entity_id: leadId, entity_type: 'leads', task_type_id: 1
  }];
}
return [{ json: { ...prep, lead_id: leadId, notas: [{ note_type: 'common', params: { text: prep.nota } }], tarefa } }];
